  1→import fs from 'fs';
  2→import path from 'path';
  3→
  4→import {
  5→  ASSISTANT_NAME,
  6→  CREDENTIAL_PROXY_PORT,
  7→  IDLE_TIMEOUT,
  8→  POLL_INTERVAL,
  9→  TIMEZONE,
 10→  TRIGGER_PATTERN,
 11→} from './config.js';
 12→import { startCredentialProxy } from './credential-proxy.js';
 13→import './channels/index.js';
 14→import {
 15→  getChannelFactory,
 16→  getRegisteredChannelNames,
 17→} from './channels/registry.js';
 18→import {
 19→  ContainerOutput,
 20→  runContainerAgent,
 21→  writeGroupsSnapshot,
 22→  writeTasksSnapshot,
 23→} from './container-runner.js';
 24→import {
 25→  cleanupOrphans,
 26→  ensureContainerRuntimeRunning,
 27→  PROXY_BIND_HOST,
 28→} from './container-runtime.js';
 29→import {
 30→  getAllChats,
 31→  getAllRegisteredGroups,
 32→  getAllSessions,
 33→  getAllTasks,
 34→  getMessagesSince,
 35→  getNewMessages,
 36→  getRouterState,
 37→  initDatabase,
 38→  setRegisteredGroup,
 39→  setRouterState,
 40→  setSession,
 41→  storeChatMetadata,
 42→  storeMessage,
 43→} from './db.js';
 44→import { GroupQueue } from './group-queue.js';
 45→import { resolveGroupFolderPath } from './group-folder.js';
 46→import { startIpcWatcher } from './ipc.js';
 47→import { findChannel, formatMessages, formatOutbound } from './router.js';
 48→import {
 49→  restoreRemoteControl,
 50→  startRemoteControl,
 51→  stopRemoteControl,
 52→} from './remote-control.js';
 53→import {
 54→  isSenderAllowed,
 55→  isTriggerAllowed,
 56→  loadSenderAllowlist,
 57→  shouldDropMessage,
 58→} from './sender-allowlist.js';
 59→import { startSchedulerLoop } from './task-scheduler.js';
 60→import { Channel, NewMessage, RegisteredGroup } from './types.js';
 61→import { logger } from './logger.js';
 62→
 63→// Re-export for backwards compatibility during refactor
 64→export { escapeXml, formatMessages } from './router.js';
 65→
 66→let lastTimestamp = '';
 67→let sessions: Record<string, string> = {};
 68→let registeredGroups: Record<string, RegisteredGroup> = {};
 69→let lastAgentTimestamp: Record<string, string> = {};
 70→let messageLoopRunning = false;
 71→
 72→const channels: Channel[] = [];
 73→const queue = new GroupQueue();
 74→
 75→function loadState(): void {
 76→  lastTimestamp = getRouterState('last_timestamp') || '';
 77→  const agentTs = getRouterState('last_agent_timestamp');
 78→  try {
 79→    lastAgentTimestamp = agentTs ? JSON.parse(agentTs) : {};
 80→  } catch {
 81→    logger.warn('Corrupted last_agent_timestamp in DB, resetting');
 82→    lastAgentTimestamp = {};
 83→  }
 84→  sessions = getAllSessions();
 85→  registeredGroups = getAllRegisteredGroups();
 86→  logger.info(
 87→    { groupCount: Object.keys(registeredGroups).length },
 88→    'State loaded',
 89→  );
 90→}
 91→
 92→function saveState(): void {
 93→  setRouterState('last_timestamp', lastTimestamp);
 94→  setRouterState('last_agent_timestamp', JSON.stringify(lastAgentTimestamp));
 95→}
 96→
 97→function registerGroup(jid: string, group: RegisteredGroup): void {
 98→  let groupDir: string;
 99→  try {
100→    groupDir = resolveGroupFolderPath(group.folder);
101→  } catch (err) {
102→    logger.warn(
103→      { jid, folder: group.folder, err },
104→      'Rejecting group registration with invalid folder',
105→    );
106→    return;
107→  }
108→
109→  registeredGroups[jid] = group;
110→  setRegisteredGroup(jid, group);
111→
112→  // Create group folder
113→  fs.mkdirSync(path.join(groupDir, 'logs'), { recursive: true });
114→
115→  logger.info(
116→    { jid, name: group.name, folder: group.folder },
117→    'Group registered',
118→  );
119→}
120→
121→/**
122→ * Get available groups list for the agent.
123→ * Returns groups ordered by most recent activity.
124→ */
125→export function getAvailableGroups(): import('./container-runner.js').AvailableGroup[] {
126→  const chats = getAllChats();
127→  const registeredJids = new Set(Object.keys(registeredGroups));
128→
129→  return chats
130→    .filter((c) => c.jid !== '__group_sync__' && c.is_group)
131→    .map((c) => ({
132→      jid: c.jid,
133→      name: c.name,
134→      lastActivity: c.last_message_time,
135→      isRegistered: registeredJids.has(c.jid),
136→    }));
137→}
138→
139→/** @internal - exported for testing */
140→export function _setRegisteredGroups(
141→  groups: Record<string, RegisteredGroup>,
142→): void {
143→  registeredGroups = groups;
144→}
145→
146→/**
147→ * Process all pending messages for a group.
148→ * Called by the GroupQueue when it's this group's turn.
149→ */
150→async function processGroupMessages(chatJid: string): Promise<boolean> {
151→  const group = registeredGroups[chatJid];
152→  if (!group) return true;
153→
154→  const channel = findChannel(channels, chatJid);
155→  if (!channel) {
156→    logger.warn({ chatJid }, 'No channel owns JID, skipping messages');
157→    return true;
158→  }
159→
160→  const isMainGroup = group.isMain === true;
161→
162→  const sinceTimestamp = lastAgentTimestamp[chatJid] || '';
163→  const missedMessages = getMessagesSince(
164→    chatJid,
165→    sinceTimestamp,
166→    ASSISTANT_NAME,
167→  );
168→
169→  if (missedMessages.length === 0) return true;
170→
171→  // For non-main groups, check if trigger is required and present
172→  if (!isMainGroup && group.requiresTrigger !== false) {
173→    const allowlistCfg = loadSenderAllowlist();
174→    const hasTrigger = missedMessages.some(
175→      (m) =>
176→        TRIGGER_PATTERN.test(m.content.trim()) &&
177→        (m.is_from_me || isTriggerAllowed(chatJid, m.sender, allowlistCfg)),
178→    );
179→    if (!hasTrigger) return true;
180→  }
181→
182→  const prompt = formatMessages(missedMessages, TIMEZONE);
183→
184→  // Advance cursor so the piping path in startMessageLoop won't re-fetch
185→  // these messages. Save the old cursor so we can roll back on error.
186→  const previousCursor = lastAgentTimestamp[chatJid] || '';
187→  lastAgentTimestamp[chatJid] =
188→    missedMessages[missedMessages.length - 1].timestamp;
189→  saveState();
190→
191→  logger.info(
192→    { group: group.name, messageCount: missedMessages.length },
193→    'Processing messages',
194→  );
195→
196→  // Track idle timer for closing stdin when agent is idle
197→  let idleTimer: ReturnType<typeof setTimeout> | null = null;
198→
199→  const resetIdleTimer = () => {
200→    if (idleTimer) clearTimeout(idleTimer);
201→    idleTimer = setTimeout(() => {
202→      logger.debug(
203→        { group: group.name },
204→        'Idle timeout, closing container stdin',
205→      );
206→      queue.closeStdin(chatJid);
207→    }, IDLE_TIMEOUT);
208→  };
209→
210→  await channel.setTyping?.(chatJid, true);
211→  let hadError = false;
212→  let outputSentToUser = false;
213→
214→  const output = await runAgent(group, prompt, chatJid, async (result) => {
215→    // Streaming output callback — called for each agent result
216→    if (result.result) {
217→      const raw =
218→        typeof result.result === 'string'
219→          ? result.result
220→          : JSON.stringify(result.result);
221→      // Strip <internal>...</internal> blocks — agent uses these for internal reasoning
222→      const text = raw.replace(/<internal>[\s\S]*?<\/internal>/g, '').trim();
223→      logger.info({ group: group.name }, `Agent output: ${raw.length} chars`);
224→      if (text) {
225→        await channel.sendMessage(chatJid, text);
226→        outputSentToUser = true;
227→      }
228→      // Only reset idle timer on actual results, not session-update markers (result: null)
229→      resetIdleTimer();
230→    }
231→
232→    if (result.status === 'success') {
233→      queue.notifyIdle(chatJid);
234→    }
235→
236→    if (result.status === 'error') {
237→      hadError = true;
238→    }
239→  });
240→
241→  await channel.setTyping?.(chatJid, false);
242→  if (idleTimer) clearTimeout(idleTimer);
243→
244→  if (output === 'error' || hadError) {
245→    // If we already sent output to the user, don't roll back the cursor —
246→    // the user got their response and re-processing would send duplicates.
247→    if (outputSentToUser) {
248→      logger.warn(
249→        { group: group.name },
250→        'Agent error after output was sent, skipping cursor rollback to prevent duplicates',
251→      );
252→      return true;
253→    }
254→    // Roll back cursor so retries can re-process these messages
255→    lastAgentTimestamp[chatJid] = previousCursor;
256→    saveState();
257→    logger.warn(
258→      { group: group.name },
259→      'Agent error, rolled back message cursor for retry',
260→    );
261→    return false;
262→  }
263→
264→  return true;
265→}
266→
267→async function runAgent(
268→  group: RegisteredGroup,
269→  prompt: string,
270→  chatJid: string,
271→  onOutput?: (output: ContainerOutput) => Promise<void>,
272→): Promise<'success' | 'error'> {
273→  const isMain = group.isMain === true;
274→  const sessionId = sessions[group.folder];
275→
276→  // Update tasks snapshot for container to read (filtered by group)
277→  const tasks = getAllTasks();
278→  writeTasksSnapshot(
279→    group.folder,
280→    isMain,
281→    tasks.map((t) => ({
282→      id: t.id,
283→      groupFolder: t.group_folder,
284→      prompt: t.prompt,
285→      schedule_type: t.schedule_type,
286→      schedule_value: t.schedule_value,
287→      status: t.status,
288→      next_run: t.next_run,
289→    })),
290→  );
291→
292→  // Update available groups snapshot (main group only can see all groups)
293→  const availableGroups = getAvailableGroups();
294→  writeGroupsSnapshot(
295→    group.folder,
296→    isMain,
297→    availableGroups,
298→    new Set(Object.keys(registeredGroups)),
299→  );
300→
301→  // Wrap onOutput to track session ID from streamed results
302→  const wrappedOnOutput = onOutput
303→    ? async (output: ContainerOutput) => {
304→        if (output.newSessionId) {
305→          sessions[group.folder] = output.newSessionId;
306→          setSession(group.folder, output.newSessionId);
307→        }
308→        await onOutput(output);
309→      }
310→    : undefined;
311→
312→  try {
313→    const output = await runContainerAgent(
314→      group,
315→      {
316→        prompt,
317→        sessionId,
318→        groupFolder: group.folder,
319→        chatJid,
320→        isMain,
321→        assistantName: ASSISTANT_NAME,
322→      },
323→      (proc, containerName) =>
324→        queue.registerProcess(chatJid, proc, containerName, group.folder),
325→      wrappedOnOutput,
326→    );
327→
328→    if (output.newSessionId) {
329→      sessions[group.folder] = output.newSessionId;
330→      setSession(group.folder, output.newSessionId);
331→    }
332→
333→    if (output.status === 'error') {
334→      logger.error(
335→        { group: group.name, error: output.error },
336→        'Container agent error',
337→      );
338→      return 'error';
339→    }
340→
341→    return 'success';
342→  } catch (err) {
343→    logger.error({ group: group.name, err }, 'Agent error');
344→    return 'error';
345→  }
346→}
347→
348→async function startMessageLoop(): Promise<void> {
349→  if (messageLoopRunning) {
350→    logger.debug('Message loop already running, skipping duplicate start');
351→    return;
352→  }
353→  messageLoopRunning = true;
354→
355→  logger.info(`NanoClaw running (trigger: @${ASSISTANT_NAME})`);
356→
357→  while (true) {
358→    try {
359→      const jids = Object.keys(registeredGroups);
360→      const { messages, newTimestamp } = getNewMessages(
361→        jids,
362→        lastTimestamp,
363→        ASSISTANT_NAME,
364→      );
365→
366→      if (messages.length > 0) {
367→        logger.info({ count: messages.length }, 'New messages');
368→
369→        // Advance the "seen" cursor for all messages immediately
370→        lastTimestamp = newTimestamp;
371→        saveState();
372→
373→        // Deduplicate by group
374→        const messagesByGroup = new Map<string, NewMessage[]>();
375→        for (const msg of messages) {
376→          const existing = messagesByGroup.get(msg.chat_jid);
377→          if (existing) {
378→            existing.push(msg);
379→          } else {
380→            messagesByGroup.set(msg.chat_jid, [msg]);
381→          }
382→        }
383→
384→        for (const [chatJid, groupMessages] of messagesByGroup) {
385→          const group = registeredGroups[chatJid];
386→          if (!group) continue;
387→
388→          const channel = findChannel(channels, chatJid);
389→          if (!channel) {
390→            logger.warn({ chatJid }, 'No channel owns JID, skipping messages');
391→            continue;
392→          }
393→
394→          const isMainGroup = group.isMain === true;
395→          const needsTrigger = !isMainGroup && group.requiresTrigger !== false;
396→
397→          // For non-main groups, only act on trigger messages.
398→          // Non-trigger messages accumulate in DB and get pulled as
399→          // context when a trigger eventually arrives.
400→          if (needsTrigger) {
401→            const allowlistCfg = loadSenderAllowlist();
402→            const hasTrigger = groupMessages.some(
403→              (m) =>
404→                TRIGGER_PATTERN.test(m.content.trim()) &&
405→                (m.is_from_me ||
406→                  isTriggerAllowed(chatJid, m.sender, allowlistCfg)),
407→            );
408→            if (!hasTrigger) continue;
409→          }
410→
411→          // Pull all messages since lastAgentTimestamp so non-trigger
412→          // context that accumulated between triggers is included.
413→          const allPending = getMessagesSince(
414→            chatJid,
415→            lastAgentTimestamp[chatJid] || '',
416→            ASSISTANT_NAME,
417→          );
418→          const messagesToSend =
419→            allPending.length > 0 ? allPending : groupMessages;
420→          const formatted = formatMessages(messagesToSend, TIMEZONE);
421→
422→          if (queue.sendMessage(chatJid, formatted)) {
423→            logger.debug(
424→              { chatJid, count: messagesToSend.length },
425→              'Piped messages to active container',
426→            );
427→            lastAgentTimestamp[chatJid] =
428→              messagesToSend[messagesToSend.length - 1].timestamp;
429→            saveState();
430→            // Show typing indicator while the container processes the piped message
431→            channel
432→              .setTyping?.(chatJid, true)
433→              ?.catch((err) =>
434→                logger.warn({ chatJid, err }, 'Failed to set typing indicator'),
435→              );
436→          } else {
437→            // No active container — enqueue for a new one
438→            queue.enqueueMessageCheck(chatJid);
439→          }
440→        }
441→      }
442→    } catch (err) {
443→      logger.error({ err }, 'Error in message loop');
444→    }
445→    await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL));
446→  }
447→}
448→
449→/**
450→ * Startup recovery: check for unprocessed messages in registered groups.
451→ * Handles crash between advancing lastTimestamp and processing messages.
452→ */
453→function recoverPendingMessages(): void {
454→  for (const [chatJid, group] of Object.entries(registeredGroups)) {
455→    const sinceTimestamp = lastAgentTimestamp[chatJid] || '';
456→    const pending = getMessagesSince(chatJid, sinceTimestamp, ASSISTANT_NAME);
457→    if (pending.length > 0) {
458→      logger.info(
459→        { group: group.name, pendingCount: pending.length },
460→        'Recovery: found unprocessed messages',
461→      );
462→      queue.enqueueMessageCheck(chatJid);
463→    }
464→  }
465→}
466→
467→function ensureContainerSystemRunning(): void {
468→  ensureContainerRuntimeRunning();
469→  cleanupOrphans();
470→}
471→
472→async function main(): Promise<void> {
473→  ensureContainerSystemRunning();
474→  initDatabase();
475→  logger.info('Database initialized');
476→  loadState();
477→  restoreRemoteControl();
478→
479→  // Start credential proxy (containers route API calls through this)
480→  const proxyServer = await startCredentialProxy(
481→    CREDENTIAL_PROXY_PORT,
482→    PROXY_BIND_HOST,
483→  );
484→
485→  // Graceful shutdown handlers
486→  const shutdown = async (signal: string) => {
487→    logger.info({ signal }, 'Shutdown signal received');
488→    proxyServer.close();
489→    await queue.shutdown(10000);
490→    for (const ch of channels) await ch.disconnect();
491→    process.exit(0);
492→  };
493→  process.on('SIGTERM', () => shutdown('SIGTERM'));
494→  process.on('SIGINT', () => shutdown('SIGINT'));
495→
496→  // Handle /remote-control and /remote-control-end commands
497→  async function handleRemoteControl(
498→    command: string,
499→    chatJid: string,
500→    msg: NewMessage,
501→  ): Promise<void> {
502→    const group = registeredGroups[chatJid];
503→    if (!group?.isMain) {
504→      logger.warn(
505→        { chatJid, sender: msg.sender },
506→        'Remote control rejected: not main group',
507→      );
508→      return;
509→    }
510→
511→    const channel = findChannel(channels, chatJid);
512→    if (!channel) return;
513→
514→    if (command === '/remote-control') {
515→      const result = await startRemoteControl(
516→        msg.sender,
517→        chatJid,
518→        process.cwd(),
519→      );
520→      if (result.ok) {
521→        await channel.sendMessage(chatJid, result.url);
522→      } else {
523→        await channel.sendMessage(
524→          chatJid,
525→          `Remote Control failed: ${result.error}`,
526→        );
527→      }
528→    } else {
529→      const result = stopRemoteControl();
530→      if (result.ok) {
531→        await channel.sendMessage(chatJid, 'Remote Control session ended.');
532→      } else {
533→        await channel.sendMessage(chatJid, result.error);
534→      }
535→    }
536→  }
537→
538→  // Channel callbacks (shared by all channels)
539→  const channelOpts = {
540→    onMessage: (chatJid: string, msg: NewMessage) => {
541→      // Remote control commands — intercept before storage
542→      const trimmed = msg.content.trim();
543→      if (trimmed === '/remote-control' || trimmed === '/remote-control-end') {
544→        handleRemoteControl(trimmed, chatJid, msg).catch((err) =>
545→          logger.error({ err, chatJid }, 'Remote control command error'),
546→        );
547→        return;
548→      }
549→
550→      // Sender allowlist drop mode: discard messages from denied senders before storing
551→      if (!msg.is_from_me && !msg.is_bot_message && registeredGroups[chatJid]) {
552→        const cfg = loadSenderAllowlist();
553→        if (
554→          shouldDropMessage(chatJid, cfg) &&
555→          !isSenderAllowed(chatJid, msg.sender, cfg)
556→        ) {
557→          if (cfg.logDenied) {
558→            logger.debug(
559→              { chatJid, sender: msg.sender },
560→              'sender-allowlist: dropping message (drop mode)',
561→            );
562→          }
563→          return;
564→        }
565→      }
566→      storeMessage(msg);
567→    },
568→    onChatMetadata: (
569→      chatJid: string,
570→      timestamp: string,
571→      name?: string,
572→      channel?: string,
573→      isGroup?: boolean,
574→    ) => storeChatMetadata(chatJid, timestamp, name, channel, isGroup),
575→    registeredGroups: () => registeredGroups,
576→  };
577→
578→  // Create and connect all registered channels.
579→  // Each channel self-registers via the barrel import above.
580→  // Factories return null when credentials are missing, so unconfigured channels are skipped.
581→  for (const channelName of getRegisteredChannelNames()) {
582→    const factory = getChannelFactory(channelName)!;
583→    const channel = factory(channelOpts);
584→    if (!channel) {
585→      logger.warn(
586→        { channel: channelName },
587→        'Channel installed but credentials missing — skipping. Check .env or re-run the channel skill.',
588→      );
589→      continue;
590→    }
591→    channels.push(channel);
592→    await channel.connect();
593→  }
594→  if (channels.length === 0) {
595→    logger.fatal('No channels connected');
596→    process.exit(1);
597→  }
598→
599→  // Start subsystems (independently of connection handler)
600→  startSchedulerLoop({
601→    registeredGroups: () => registeredGroups,
602→    getSessions: () => sessions,
603→    queue,
604→    onProcess: (groupJid, proc, containerName, groupFolder) =>
605→      queue.registerProcess(groupJid, proc, containerName, groupFolder),
606→    sendMessage: async (jid, rawText) => {
607→      const channel = findChannel(channels, jid);
608→      if (!channel) {
609→        logger.warn({ jid }, 'No channel owns JID, cannot send message');
610→        return;
611→      }
612→      const text = formatOutbound(rawText);
613→      if (text) await channel.sendMessage(jid, text);
614→    },
615→  });
616→  startIpcWatcher({
617→    sendMessage: (jid, text) => {
618→      const channel = findChannel(channels, jid);
619→      if (!channel) throw new Error(`No channel for JID: ${jid}`);
620→      return channel.sendMessage(jid, text);
621→    },
622→    registeredGroups: () => registeredGroups,
623→    registerGroup,
624→    syncGroups: async (force: boolean) => {
625→      await Promise.all(
626→        channels
627→          .filter((ch) => ch.syncGroups)
628→          .map((ch) => ch.syncGroups!(force)),
629→      );
630→    },
631→    getAvailableGroups,
632→    writeGroupsSnapshot: (gf, im, ag, rj) =>
633→      writeGroupsSnapshot(gf, im, ag, rj),
634→    onTasksChanged: () => {
635→      const tasks = getAllTasks();
636→      const taskRows = tasks.map((t) => ({
637→        id: t.id,
638→        groupFolder: t.group_folder,
639→        prompt: t.prompt,
640→        schedule_type: t.schedule_type,
641→        schedule_value: t.schedule_value,
642→        status: t.status,
643→        next_run: t.next_run,
644→      }));
645→      for (const group of Object.values(registeredGroups)) {
646→        writeTasksSnapshot(group.folder, group.isMain === true, taskRows);
647→      }
648→    },
649→  });
650→  queue.setProcessMessagesFn(processGroupMessages);
651→  recoverPendingMessages();
652→  startMessageLoop().catch((err) => {
653→    logger.fatal({ err }, 'Message loop crashed unexpectedly');
654→    process.exit(1);
655→  });
656→}
657→
658→// Guard: only run when executed directly, not when imported by tests
659→const isDirectRun =
660→  process.argv[1] &&
661→  new URL(import.meta.url).pathname ===
662→    new URL(`file://${process.argv[1]}`).pathname;
663→
664→if (isDirectRun) {
665→  main().catch((err) => {
666→    logger.error({ err }, 'Failed to start NanoClaw');
667→    process.exit(1);
668→  });
669→}
670→

