  1→import { ChildProcess } from 'child_process';
  2→import fs from 'fs';
  3→import path from 'path';
  4→
  5→import { DATA_DIR, MAX_CONCURRENT_CONTAINERS } from './config.js';
  6→import { logger } from './logger.js';
  7→
  8→interface QueuedTask {
  9→  id: string;
 10→  groupJid: string;
 11→  fn: () => Promise<void>;
 12→}
 13→
 14→const MAX_RETRIES = 5;
 15→const BASE_RETRY_MS = 5000;
 16→
 17→interface GroupState {
 18→  active: boolean;
 19→  idleWaiting: boolean;
 20→  isTaskContainer: boolean;
 21→  runningTaskId: string | null;
 22→  pendingMessages: boolean;
 23→  pendingTasks: QueuedTask[];
 24→  process: ChildProcess | null;
 25→  containerName: string | null;
 26→  groupFolder: string | null;
 27→  retryCount: number;
 28→}
 29→
 30→export class GroupQueue {
 31→  private groups = new Map<string, GroupState>();
 32→  private activeCount = 0;
 33→  private waitingGroups: string[] = [];
 34→  private processMessagesFn: ((groupJid: string) => Promise<boolean>) | null =
 35→    null;
 36→  private shuttingDown = false;
 37→
 38→  private getGroup(groupJid: string): GroupState {
 39→    let state = this.groups.get(groupJid);
 40→    if (!state) {
 41→      state = {
 42→        active: false,
 43→        idleWaiting: false,
 44→        isTaskContainer: false,
 45→        runningTaskId: null,
 46→        pendingMessages: false,
 47→        pendingTasks: [],
 48→        process: null,
 49→        containerName: null,
 50→        groupFolder: null,
 51→        retryCount: 0,
 52→      };
 53→      this.groups.set(groupJid, state);
 54→    }
 55→    return state;
 56→  }
 57→
 58→  setProcessMessagesFn(fn: (groupJid: string) => Promise<boolean>): void {
 59→    this.processMessagesFn = fn;
 60→  }
 61→
 62→  enqueueMessageCheck(groupJid: string): void {
 63→    if (this.shuttingDown) return;
 64→
 65→    const state = this.getGroup(groupJid);
 66→
 67→    if (state.active) {
 68→      state.pendingMessages = true;
 69→      logger.debug({ groupJid }, 'Container active, message queued');
 70→      return;
 71→    }
 72→
 73→    if (this.activeCount >= MAX_CONCURRENT_CONTAINERS) {
 74→      state.pendingMessages = true;
 75→      if (!this.waitingGroups.includes(groupJid)) {
 76→        this.waitingGroups.push(groupJid);
 77→      }
 78→      logger.debug(
 79→        { groupJid, activeCount: this.activeCount },
 80→        'At concurrency limit, message queued',
 81→      );
 82→      return;
 83→    }
 84→
 85→    this.runForGroup(groupJid, 'messages').catch((err) =>
 86→      logger.error({ groupJid, err }, 'Unhandled error in runForGroup'),
 87→    );
 88→  }
 89→
 90→  enqueueTask(groupJid: string, taskId: string, fn: () => Promise<void>): void {
 91→    if (this.shuttingDown) return;
 92→
 93→    const state = this.getGroup(groupJid);
 94→
 95→    // Prevent double-queuing: check both pending and currently-running task
 96→    if (state.runningTaskId === taskId) {
 97→      logger.debug({ groupJid, taskId }, 'Task already running, skipping');
 98→      return;
 99→    }
100→    if (state.pendingTasks.some((t) => t.id === taskId)) {
101→      logger.debug({ groupJid, taskId }, 'Task already queued, skipping');
102→      return;
103→    }
104→
105→    if (state.active) {
106→      state.pendingTasks.push({ id: taskId, groupJid, fn });
107→      if (state.idleWaiting) {
108→        this.closeStdin(groupJid);
109→      }
110→      logger.debug({ groupJid, taskId }, 'Container active, task queued');
111→      return;
112→    }
113→
114→    if (this.activeCount >= MAX_CONCURRENT_CONTAINERS) {
115→      state.pendingTasks.push({ id: taskId, groupJid, fn });
116→      if (!this.waitingGroups.includes(groupJid)) {
117→        this.waitingGroups.push(groupJid);
118→      }
119→      logger.debug(
120→        { groupJid, taskId, activeCount: this.activeCount },
121→        'At concurrency limit, task queued',
122→      );
123→      return;
124→    }
125→
126→    // Run immediately
127→    this.runTask(groupJid, { id: taskId, groupJid, fn }).catch((err) =>
128→      logger.error({ groupJid, taskId, err }, 'Unhandled error in runTask'),
129→    );
130→  }
131→
132→  registerProcess(
133→    groupJid: string,
134→    proc: ChildProcess,
135→    containerName: string,
136→    groupFolder?: string,
137→  ): void {
138→    const state = this.getGroup(groupJid);
139→    state.process = proc;
140→    state.containerName = containerName;
141→    if (groupFolder) state.groupFolder = groupFolder;
142→  }
143→
144→  /**
145→   * Mark the container as idle-waiting (finished work, waiting for IPC input).
146→   * If tasks are pending, preempt the idle container immediately.
147→   */
148→  notifyIdle(groupJid: string): void {
149→    const state = this.getGroup(groupJid);
150→    state.idleWaiting = true;
151→    if (state.pendingTasks.length > 0) {
152→      this.closeStdin(groupJid);
153→    }
154→  }
155→
156→  /**
157→   * Send a follow-up message to the active container via IPC file.
158→   * Returns true if the message was written, false if no active container.
159→   */
160→  sendMessage(groupJid: string, text: string): boolean {
161→    const state = this.getGroup(groupJid);
162→    if (!state.active || !state.groupFolder || state.isTaskContainer)
163→      return false;
164→    state.idleWaiting = false; // Agent is about to receive work, no longer idle
165→
166→    const inputDir = path.join(DATA_DIR, 'ipc', state.groupFolder, 'input');
167→    try {
168→      fs.mkdirSync(inputDir, { recursive: true });
169→      const filename = `${Date.now()}-${Math.random().toString(36).slice(2, 6)}.json`;
170→      const filepath = path.join(inputDir, filename);
171→      const tempPath = `${filepath}.tmp`;
172→      fs.writeFileSync(tempPath, JSON.stringify({ type: 'message', text }));
173→      fs.renameSync(tempPath, filepath);
174→      return true;
175→    } catch {
176→      return false;
177→    }
178→  }
179→
180→  /**
181→   * Signal the active container to wind down by writing a close sentinel.
182→   */
183→  closeStdin(groupJid: string): void {
184→    const state = this.getGroup(groupJid);
185→    if (!state.active || !state.groupFolder) return;
186→
187→    const inputDir = path.join(DATA_DIR, 'ipc', state.groupFolder, 'input');
188→    try {
189→      fs.mkdirSync(inputDir, { recursive: true });
190→      fs.writeFileSync(path.join(inputDir, '_close'), '');
191→    } catch {
192→      // ignore
193→    }
194→  }
195→
196→  private async runForGroup(
197→    groupJid: string,
198→    reason: 'messages' | 'drain',
199→  ): Promise<void> {
200→    const state = this.getGroup(groupJid);
201→    state.active = true;
202→    state.idleWaiting = false;
203→    state.isTaskContainer = false;
204→    state.pendingMessages = false;
205→    this.activeCount++;
206→
207→    logger.debug(
208→      { groupJid, reason, activeCount: this.activeCount },
209→      'Starting container for group',
210→    );
211→
212→    try {
213→      if (this.processMessagesFn) {
214→        const success = await this.processMessagesFn(groupJid);
215→        if (success) {
216→          state.retryCount = 0;
217→        } else {
218→          this.scheduleRetry(groupJid, state);
219→        }
220→      }
221→    } catch (err) {
222→      logger.error({ groupJid, err }, 'Error processing messages for group');
223→      this.scheduleRetry(groupJid, state);
224→    } finally {
225→      state.active = false;
226→      state.process = null;
227→      state.containerName = null;
228→      state.groupFolder = null;
229→      this.activeCount--;
230→      this.drainGroup(groupJid);
231→    }
232→  }
233→
234→  private async runTask(groupJid: string, task: QueuedTask): Promise<void> {
235→    const state = this.getGroup(groupJid);
236→    state.active = true;
237→    state.idleWaiting = false;
238→    state.isTaskContainer = true;
239→    state.runningTaskId = task.id;
240→    this.activeCount++;
241→
242→    logger.debug(
243→      { groupJid, taskId: task.id, activeCount: this.activeCount },
244→      'Running queued task',
245→    );
246→
247→    try {
248→      await task.fn();
249→    } catch (err) {
250→      logger.error({ groupJid, taskId: task.id, err }, 'Error running task');
251→    } finally {
252→      state.active = false;
253→      state.isTaskContainer = false;
254→      state.runningTaskId = null;
255→      state.process = null;
256→      state.containerName = null;
257→      state.groupFolder = null;
258→      this.activeCount--;
259→      this.drainGroup(groupJid);
260→    }
261→  }
262→
263→  private scheduleRetry(groupJid: string, state: GroupState): void {
264→    state.retryCount++;
265→    if (state.retryCount > MAX_RETRIES) {
266→      logger.error(
267→        { groupJid, retryCount: state.retryCount },
268→        'Max retries exceeded, dropping messages (will retry on next incoming message)',
269→      );
270→      state.retryCount = 0;
271→      return;
272→    }
273→
274→    const delayMs = BASE_RETRY_MS * Math.pow(2, state.retryCount - 1);
275→    logger.info(
276→      { groupJid, retryCount: state.retryCount, delayMs },
277→      'Scheduling retry with backoff',
278→    );
279→    setTimeout(() => {
280→      if (!this.shuttingDown) {
281→        this.enqueueMessageCheck(groupJid);
282→      }
283→    }, delayMs);
284→  }
285→
286→  private drainGroup(groupJid: string): void {
287→    if (this.shuttingDown) return;
288→
289→    const state = this.getGroup(groupJid);
290→
291→    // Tasks first (they won't be re-discovered from SQLite like messages)
292→    if (state.pendingTasks.length > 0) {
293→      const task = state.pendingTasks.shift()!;
294→      this.runTask(groupJid, task).catch((err) =>
295→        logger.error(
296→          { groupJid, taskId: task.id, err },
297→          'Unhandled error in runTask (drain)',
298→        ),
299→      );
300→      return;
301→    }
302→
303→    // Then pending messages
304→    if (state.pendingMessages) {
305→      this.runForGroup(groupJid, 'drain').catch((err) =>
306→        logger.error(
307→          { groupJid, err },
308→          'Unhandled error in runForGroup (drain)',
309→        ),
310→      );
311→      return;
312→    }
313→
314→    // Nothing pending for this group; check if other groups are waiting for a slot
315→    this.drainWaiting();
316→  }
317→
318→  private drainWaiting(): void {
319→    while (
320→      this.waitingGroups.length > 0 &&
321→      this.activeCount < MAX_CONCURRENT_CONTAINERS
322→    ) {
323→      const nextJid = this.waitingGroups.shift()!;
324→      const state = this.getGroup(nextJid);
325→
326→      // Prioritize tasks over messages
327→      if (state.pendingTasks.length > 0) {
328→        const task = state.pendingTasks.shift()!;
329→        this.runTask(nextJid, task).catch((err) =>
330→          logger.error(
331→            { groupJid: nextJid, taskId: task.id, err },
332→            'Unhandled error in runTask (waiting)',
333→          ),
334→        );
335→      } else if (state.pendingMessages) {
336→        this.runForGroup(nextJid, 'drain').catch((err) =>
337→          logger.error(
338→            { groupJid: nextJid, err },
339→            'Unhandled error in runForGroup (waiting)',
340→          ),
341→        );
342→      }
343→      // If neither pending, skip this group
344→    }
345→  }
346→
347→  async shutdown(_gracePeriodMs: number): Promise<void> {
348→    this.shuttingDown = true;
349→
350→    // Count active containers but don't kill them — they'll finish on their own
351→    // via idle timeout or container timeout. The --rm flag cleans them up on exit.
352→    // This prevents WhatsApp reconnection restarts from killing working agents.
353→    const activeContainers: string[] = [];
354→    for (const [_jid, state] of this.groups) {
355→      if (state.process && !state.process.killed && state.containerName) {
356→        activeContainers.push(state.containerName);
357→      }
358→    }
359→
360→    logger.info(
361→      { activeCount: this.activeCount, detachedContainers: activeContainers },
362→      'GroupQueue shutting down (containers detached, not killed)',
363→    );
364→  }
