  1→/**
  2→ * Container Runner for NanoClaw
  3→ * Spawns agent execution in containers and handles IPC
  4→ */
  5→import { ChildProcess, exec, spawn } from 'child_process';
  6→import fs from 'fs';
  7→import path from 'path';
  8→
  9→import {
 10→  CONTAINER_IMAGE,
 11→  CONTAINER_MAX_OUTPUT_SIZE,
 12→  CONTAINER_TIMEOUT,
 13→  CREDENTIAL_PROXY_PORT,
 14→  DATA_DIR,
 15→  GROUPS_DIR,
 16→  IDLE_TIMEOUT,
 17→  TIMEZONE,
 18→} from './config.js';
 19→import { resolveGroupFolderPath, resolveGroupIpcPath } from './group-folder.js';
 20→import { logger } from './logger.js';
 21→import {
 22→  CONTAINER_HOST_GATEWAY,
 23→  CONTAINER_RUNTIME_BIN,
 24→  hostGatewayArgs,
 25→  readonlyMountArgs,
 26→  stopContainer,
 27→} from './container-runtime.js';
 28→import { detectAuthMode } from './credential-proxy.js';
 29→import { readEnvFile } from './env.js';
 30→import { validateAdditionalMounts } from './mount-security.js';
 31→import { RegisteredGroup } from './types.js';
 32→
 33→// Sentinel markers for robust output parsing (must match agent-runner)
 34→const OUTPUT_START_MARKER = '---NANOCLAW_OUTPUT_START---';
 35→const OUTPUT_END_MARKER = '---NANOCLAW_OUTPUT_END---';
 36→
 37→export interface ContainerInput {
 38→  prompt: string;
 39→  sessionId?: string;
 40→  groupFolder: string;
 41→  chatJid: string;
 42→  isMain: boolean;
 43→  isScheduledTask?: boolean;
 44→  assistantName?: string;
 45→}
 46→
 47→export interface ContainerOutput {
 48→  status: 'success' | 'error';
 49→  result: string | null;
 50→  newSessionId?: string;
 51→  error?: string;
 52→}
 53→
 54→interface VolumeMount {
 55→  hostPath: string;
 56→  containerPath: string;
 57→  readonly: boolean;
 58→}
 59→
 60→function buildVolumeMounts(
 61→  group: RegisteredGroup,
 62→  isMain: boolean,
 63→): VolumeMount[] {
 64→  const mounts: VolumeMount[] = [];
 65→  const projectRoot = process.cwd();
 66→  const groupDir = resolveGroupFolderPath(group.folder);
 67→
 68→  if (isMain) {
 69→    // Main gets the project root read-only. Writable paths the agent needs
 70→    // (group folder, IPC, .claude/) are mounted separately below.
 71→    // Read-only prevents the agent from modifying host application code
 72→    // (src/, dist/, package.json, etc.) which would bypass the sandbox
 73→    // entirely on next restart.
 74→    mounts.push({
 75→      hostPath: projectRoot,
 76→      containerPath: '/workspace/project',
 77→      readonly: true,
 78→    });
 79→
 80→    // Shadow .env so the agent cannot read secrets from the mounted project root.
 81→    // Credentials are injected by the credential proxy, never exposed to containers.
 82→    const envFile = path.join(projectRoot, '.env');
 83→    if (fs.existsSync(envFile)) {
 84→      mounts.push({
 85→        hostPath: '/dev/null',
 86→        containerPath: '/workspace/project/.env',
 87→        readonly: true,
 88→      });
 89→    }
 90→
 91→    // Main also gets its group folder as the working directory
 92→    mounts.push({
 93→      hostPath: groupDir,
 94→      containerPath: '/workspace/group',
 95→      readonly: false,
 96→    });
 97→  } else {
 98→    // Other groups only get their own folder
 99→    mounts.push({
100→      hostPath: groupDir,
101→      containerPath: '/workspace/group',
102→      readonly: false,
103→    });
104→
105→    // Global memory directory (read-only for non-main)
106→    // Only directory mounts are supported, not file mounts
107→    const globalDir = path.join(GROUPS_DIR, 'global');
108→    if (fs.existsSync(globalDir)) {
109→      mounts.push({
110→        hostPath: globalDir,
111→        containerPath: '/workspace/global',
112→        readonly: true,
113→      });
114→    }
115→  }
116→
117→  // Per-group Claude sessions directory (isolated from other groups)
118→  // Each group gets their own .claude/ to prevent cross-group session access
119→  const groupSessionsDir = path.join(
120→    DATA_DIR,
121→    'sessions',
122→    group.folder,
123→    '.claude',
124→  );
125→  fs.mkdirSync(groupSessionsDir, { recursive: true });
126→  const settingsFile = path.join(groupSessionsDir, 'settings.json');
127→  if (!fs.existsSync(settingsFile)) {
128→    fs.writeFileSync(
129→      settingsFile,
130→      JSON.stringify(
131→        {
132→          env: {
133→            // Enable agent swarms (subagent orchestration)
134→            // https://code.claude.com/docs/en/agent-teams#orchestrate-teams-of-claude-code-sessions
135→            CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS: '1',
136→            // Load CLAUDE.md from additional mounted directories
137→            // https://code.claude.com/docs/en/memory#load-memory-from-additional-directories
138→            CLAUDE_CODE_ADDITIONAL_DIRECTORIES_CLAUDE_MD: '1',
139→            // Enable Claude's memory feature (persists user preferences between sessions)
140→            // https://code.claude.com/docs/en/memory#manage-auto-memory
141→            CLAUDE_CODE_DISABLE_AUTO_MEMORY: '0',
142→          },
143→        },
144→        null,
145→        2,
146→      ) + '\n',
147→    );
148→  }
149→
150→  // Sync skills from container/skills/ into each group's .claude/skills/
151→  const skillsSrc = path.join(process.cwd(), 'container', 'skills');
152→  const skillsDst = path.join(groupSessionsDir, 'skills');
153→  if (fs.existsSync(skillsSrc)) {
154→    for (const skillDir of fs.readdirSync(skillsSrc)) {
155→      const srcDir = path.join(skillsSrc, skillDir);
156→      if (!fs.statSync(srcDir).isDirectory()) continue;
157→      const dstDir = path.join(skillsDst, skillDir);
158→      fs.cpSync(srcDir, dstDir, { recursive: true });
159→    }
160→  }
161→  mounts.push({
162→    hostPath: groupSessionsDir,
163→    containerPath: '/home/node/.claude',
164→    readonly: false,
165→  });
166→
167→  // Per-group IPC namespace: each group gets its own IPC directory
168→  // This prevents cross-group privilege escalation via IPC
169→  const groupIpcDir = resolveGroupIpcPath(group.folder);
170→  fs.mkdirSync(path.join(groupIpcDir, 'messages'), { recursive: true });
171→  fs.mkdirSync(path.join(groupIpcDir, 'tasks'), { recursive: true });
172→  fs.mkdirSync(path.join(groupIpcDir, 'input'), { recursive: true });
173→  mounts.push({
174→    hostPath: groupIpcDir,
175→    containerPath: '/workspace/ipc',
176→    readonly: false,
177→  });
178→
179→  // Copy agent-runner source into a per-group writable location so agents
180→  // can customize it (add tools, change behavior) without affecting other
181→  // groups. Recompiled on container startup via entrypoint.sh.
182→  const agentRunnerSrc = path.join(
183→    projectRoot,
184→    'container',
185→    'agent-runner',
186→    'src',
187→  );
188→  const groupAgentRunnerDir = path.join(
189→    DATA_DIR,
190→    'sessions',
191→    group.folder,
192→    'agent-runner-src',
193→  );
194→  if (!fs.existsSync(groupAgentRunnerDir) && fs.existsSync(agentRunnerSrc)) {
195→    fs.cpSync(agentRunnerSrc, groupAgentRunnerDir, { recursive: true });
196→  }
197→  mounts.push({
198→    hostPath: groupAgentRunnerDir,
199→    containerPath: '/app/src',
200→    readonly: false,
201→  });
202→
203→  // Additional mounts validated against external allowlist (tamper-proof from containers)
204→  if (group.containerConfig?.additionalMounts) {
205→    const validatedMounts = validateAdditionalMounts(
206→      group.containerConfig.additionalMounts,
207→      group.name,
208→      isMain,
209→    );
210→    mounts.push(...validatedMounts);
211→  }
212→
213→  return mounts;
214→}
215→
216→function buildContainerArgs(
217→  mounts: VolumeMount[],
218→  containerName: string,
219→): string[] {
220→  const args: string[] = ['run', '-i', '--rm', '--name', containerName];
221→
222→  // Pass host timezone so container's local time matches the user's
223→  args.push('-e', `TZ=${TIMEZONE}`);
224→
225→  // Route API traffic through the credential proxy (containers never see real secrets)
226→  args.push(
227→    '-e',
228→    `ANTHROPIC_BASE_URL=http://${CONTAINER_HOST_GATEWAY}:${CREDENTIAL_PROXY_PORT}`,
229→  );
230→
231→  // Mirror the host's auth method with a placeholder value.
232→  // API key mode: SDK sends x-api-key, proxy replaces with real key.
233→  // OAuth mode:   SDK exchanges placeholder token for temp API key,
234→  //               proxy injects real OAuth token on that exchange request.
235→  const authMode = detectAuthMode();
236→  if (authMode === 'api-key') {
237→    args.push('-e', 'ANTHROPIC_API_KEY=placeholder');
238→  } else {
239→    args.push('-e', 'CLAUDE_CODE_OAUTH_TOKEN=placeholder');
240→  }
241→
242→  // Pass API tokens if configured
243→  const envSecrets = readEnvFile(['VERCEL_API_TOKEN', 'YOUTUBE_API_KEY']);
244→  if (envSecrets.VERCEL_API_TOKEN) {
245→    args.push('-e', `VERCEL_API_TOKEN=${envSecrets.VERCEL_API_TOKEN}`);
246→  }
247→  if (envSecrets.YOUTUBE_API_KEY) {
248→    args.push('-e', `YOUTUBE_API_KEY=${envSecrets.YOUTUBE_API_KEY}`);
249→  }
250→
251→  // Pass max agent turns limit (default 50 in agent-runner)
252→  const maxTurns = process.env.MAX_AGENT_TURNS;
253→  if (maxTurns) {
254→    args.push('-e', `MAX_AGENT_TURNS=${maxTurns}`);
255→  }
256→
257→  // Runtime-specific args for host gateway resolution
258→  args.push(...hostGatewayArgs());
259→
260→  // Run as host user so bind-mounted files are accessible.
261→  // Skip when running as root (uid 0), as the container's node user (uid 1000),
262→  // or when getuid is unavailable (native Windows without WSL).
263→  const hostUid = process.getuid?.();
264→  const hostGid = process.getgid?.();
265→  if (hostUid != null && hostUid !== 0 && hostUid !== 1000) {
266→    args.push('--user', `${hostUid}:${hostGid}`);
267→    args.push('-e', 'HOME=/home/node');
268→  }
269→
270→  for (const mount of mounts) {
271→    if (mount.readonly) {
272→      args.push(...readonlyMountArgs(mount.hostPath, mount.containerPath));
273→    } else {
274→      args.push('-v', `${mount.hostPath}:${mount.containerPath}`);
275→    }
276→  }
277→
278→  args.push(CONTAINER_IMAGE);
279→
280→  return args;
281→}
282→
283→export async function runContainerAgent(
284→  group: RegisteredGroup,
285→  input: ContainerInput,
286→  onProcess: (proc: ChildProcess, containerName: string) => void,
287→  onOutput?: (output: ContainerOutput) => Promise<void>,
288→): Promise<ContainerOutput> {
289→  const startTime = Date.now();
290→
291→  const groupDir = resolveGroupFolderPath(group.folder);
292→  fs.mkdirSync(groupDir, { recursive: true });
293→
294→  const mounts = buildVolumeMounts(group, input.isMain);
295→  const safeName = group.folder.replace(/[^a-zA-Z0-9-]/g, '-');
296→  const containerName = `nanoclaw-${safeName}-${Date.now()}`;
297→  const containerArgs = buildContainerArgs(mounts, containerName);
298→
299→  logger.debug(
300→    {
301→      group: group.name,
302→      containerName,
303→      mounts: mounts.map(
304→        (m) =>
305→          `${m.hostPath} -> ${m.containerPath}${m.readonly ? ' (ro)' : ''}`,
306→      ),
307→      containerArgs: containerArgs.join(' '),
308→    },
309→    'Container mount configuration',
310→  );
311→
312→  logger.info(
313→    {
314→      group: group.name,
315→      containerName,
316→      mountCount: mounts.length,
317→      isMain: input.isMain,
318→    },
319→    'Spawning container agent',
320→  );
321→
322→  const logsDir = path.join(groupDir, 'logs');
323→  fs.mkdirSync(logsDir, { recursive: true });
324→
325→  return new Promise((resolve) => {
326→    const container = spawn(CONTAINER_RUNTIME_BIN, containerArgs, {
327→      stdio: ['pipe', 'pipe', 'pipe'],
328→    });
329→
330→    onProcess(container, containerName);
331→
332→    let stdout = '';
333→    let stderr = '';
334→    let stdoutTruncated = false;
335→    let stderrTruncated = false;
336→
337→    container.stdin.write(JSON.stringify(input));
338→    container.stdin.end();
339→
340→    // Streaming output: parse OUTPUT_START/END marker pairs as they arrive
341→    let parseBuffer = '';
342→    let newSessionId: string | undefined;
343→    let outputChain = Promise.resolve();
344→
345→    container.stdout.on('data', (data) => {
346→      const chunk = data.toString();
347→
348→      // Always accumulate for logging
349→      if (!stdoutTruncated) {
350→        const remaining = CONTAINER_MAX_OUTPUT_SIZE - stdout.length;
351→        if (chunk.length > remaining) {
352→          stdout += chunk.slice(0, remaining);
353→          stdoutTruncated = true;
354→          logger.warn(
355→            { group: group.name, size: stdout.length },
356→            'Container stdout truncated due to size limit',
357→          );
358→        } else {
359→          stdout += chunk;
360→        }
361→      }
362→
363→      // Stream-parse for output markers
364→      if (onOutput) {
365→        parseBuffer += chunk;
366→        let startIdx: number;
367→        while ((startIdx = parseBuffer.indexOf(OUTPUT_START_MARKER)) !== -1) {
368→          const endIdx = parseBuffer.indexOf(OUTPUT_END_MARKER, startIdx);
369→          if (endIdx === -1) break; // Incomplete pair, wait for more data
370→
371→          const jsonStr = parseBuffer
372→            .slice(startIdx + OUTPUT_START_MARKER.length, endIdx)
373→            .trim();
374→          parseBuffer = parseBuffer.slice(endIdx + OUTPUT_END_MARKER.length);
375→
376→          try {
377→            const parsed: ContainerOutput = JSON.parse(jsonStr);
378→            if (parsed.newSessionId) {
379→              newSessionId = parsed.newSessionId;
380→            }
381→            hadStreamingOutput = true;
382→            // Activity detected — reset the hard timeout
383→            resetTimeout();
384→            // Call onOutput for all markers (including null results)
385→            // so idle timers start even for "silent" query completions.
386→            outputChain = outputChain.then(() => onOutput(parsed));
387→          } catch (err) {
388→            logger.warn(
389→              { group: group.name, error: err },
390→              'Failed to parse streamed output chunk',
391→            );
392→          }
393→        }
394→      }
395→    });
396→
397→    container.stderr.on('data', (data) => {
398→      const chunk = data.toString();
399→      const lines = chunk.trim().split('\n');
400→      for (const line of lines) {
401→        if (!line) continue;
402→        if (line.includes('[OLLAMA]')) {
403→          logger.info({ container: group.folder }, line);
404→        } else {
405→          logger.debug({ container: group.folder }, line);
406→        }
407→      }
408→      // Don't reset timeout on stderr — SDK writes debug logs continuously.
409→      // Timeout only resets on actual output (OUTPUT_MARKER in stdout).
410→      if (stderrTruncated) return;
411→      const remaining = CONTAINER_MAX_OUTPUT_SIZE - stderr.length;
412→      if (chunk.length > remaining) {
413→        stderr += chunk.slice(0, remaining);
414→        stderrTruncated = true;
415→        logger.warn(
416→          { group: group.name, size: stderr.length },
417→          'Container stderr truncated due to size limit',
418→        );
419→      } else {
420→        stderr += chunk;
421→      }
422→    });
423→
424→    let timedOut = false;
425→    let hadStreamingOutput = false;
426→    const configTimeout = group.containerConfig?.timeout || CONTAINER_TIMEOUT;
427→    // Grace period: hard timeout must be at least IDLE_TIMEOUT + 30s so the
428→    // graceful _close sentinel has time to trigger before the hard kill fires.
429→    const timeoutMs = Math.max(configTimeout, IDLE_TIMEOUT + 30_000);
430→
431→    const killOnTimeout = () => {
432→      timedOut = true;
433→      logger.error(
434→        { group: group.name, containerName },
435→        'Container timeout, stopping gracefully',
436→      );
437→      exec(stopContainer(containerName), { timeout: 15000 }, (err) => {
438→        if (err) {
439→          logger.warn(
440→            { group: group.name, containerName, err },
441→            'Graceful stop failed, force killing',
442→          );
443→          container.kill('SIGKILL');
444→        }
445→      });
446→    };
447→
448→    let timeout = setTimeout(killOnTimeout, timeoutMs);
449→
450→    // Reset the timeout whenever there's activity (streaming output)
451→    const resetTimeout = () => {
452→      clearTimeout(timeout);
453→      timeout = setTimeout(killOnTimeout, timeoutMs);
454→    };
455→
456→    container.on('close', (code) => {
457→      clearTimeout(timeout);
458→      const duration = Date.now() - startTime;
459→
460→      if (timedOut) {
461→        const ts = new Date().toISOString().replace(/[:.]/g, '-');
462→        const timeoutLog = path.join(logsDir, `container-${ts}.log`);
463→        fs.writeFileSync(
464→          timeoutLog,
465→          [
466→            `=== Container Run Log (TIMEOUT) ===`,
467→            `Timestamp: ${new Date().toISOString()}`,
468→            `Group: ${group.name}`,
469→            `Container: ${containerName}`,
470→            `Duration: ${duration}ms`,
471→            `Exit Code: ${code}`,
472→            `Had Streaming Output: ${hadStreamingOutput}`,
473→          ].join('\n'),
474→        );
475→
476→        // Timeout after output = idle cleanup, not failure.
477→        // The agent already sent its response; this is just the
478→        // container being reaped after the idle period expired.
479→        if (hadStreamingOutput) {
480→          logger.info(
481→            { group: group.name, containerName, duration, code },
482→            'Container timed out after output (idle cleanup)',
483→          );
484→          outputChain.then(() => {
485→            resolve({
486→              status: 'success',
487→              result: null,
488→              newSessionId,
489→            });
490→          });
491→          return;
492→        }
493→
494→        logger.error(
495→          { group: group.name, containerName, duration, code },
496→          'Container timed out with no output',
497→        );
498→
499→        resolve({
500→          status: 'error',
501→          result: null,
502→          error: `Container timed out after ${configTimeout}ms`,
503→        });
504→        return;
505→      }
506→
507→      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
508→      const logFile = path.join(logsDir, `container-${timestamp}.log`);
509→      const isVerbose =
510→        process.env.LOG_LEVEL === 'debug' || process.env.LOG_LEVEL === 'trace';
511→
512→      const logLines = [
513→        `=== Container Run Log ===`,
514→        `Timestamp: ${new Date().toISOString()}`,
515→        `Group: ${group.name}`,
516→        `IsMain: ${input.isMain}`,
517→        `Duration: ${duration}ms`,
518→        `Exit Code: ${code}`,
519→        `Stdout Truncated: ${stdoutTruncated}`,
520→        `Stderr Truncated: ${stderrTruncated}`,
521→        ``,
522→      ];
523→
524→      const isError = code !== 0;
525→
526→      if (isVerbose || isError) {
527→        // On error, log input metadata only — not the full prompt.
528→        // Full input is only included at verbose level to avoid
529→        // persisting user conversation content on every non-zero exit.
530→        if (isVerbose) {
531→          logLines.push(`=== Input ===`, JSON.stringify(input, null, 2), ``);
532→        } else {
533→          logLines.push(
534→            `=== Input Summary ===`,
535→            `Prompt length: ${input.prompt.length} chars`,
536→            `Session ID: ${input.sessionId || 'new'}`,
537→            ``,
538→          );
539→        }
540→        logLines.push(
541→          `=== Container Args ===`,
542→          containerArgs.join(' '),
543→          ``,
544→          `=== Mounts ===`,
545→          mounts
546→            .map(
547→              (m) =>
548→                `${m.hostPath} -> ${m.containerPath}${m.readonly ? ' (ro)' : ''}`,
549→            )
550→            .join('\n'),
551→          ``,
552→          `=== Stderr${stderrTruncated ? ' (TRUNCATED)' : ''} ===`,
553→          stderr,
554→          ``,
555→          `=== Stdout${stdoutTruncated ? ' (TRUNCATED)' : ''} ===`,
556→          stdout,
557→        );
558→      } else {
559→        logLines.push(
560→          `=== Input Summary ===`,
561→          `Prompt length: ${input.prompt.length} chars`,
562→          `Session ID: ${input.sessionId || 'new'}`,
563→          ``,
564→          `=== Mounts ===`,
565→          mounts
566→            .map((m) => `${m.containerPath}${m.readonly ? ' (ro)' : ''}`)
567→            .join('\n'),
568→          ``,
569→        );
570→      }
571→
572→      fs.writeFileSync(logFile, logLines.join('\n'));
573→      logger.debug({ logFile, verbose: isVerbose }, 'Container log written');
574→
575→      if (code !== 0) {
576→        logger.error(
577→          {
578→            group: group.name,
579→            code,
580→            duration,
581→            stderr,
582→            stdout,
583→            logFile,
584→          },
585→          'Container exited with error',
586→        );
587→
588→        resolve({
589→          status: 'error',
590→          result: null,
591→          error: `Container exited with code ${code}: ${stderr.slice(-200)}`,
592→        });
593→        return;
594→      }
595→
596→      // Streaming mode: wait for output chain to settle, return completion marker
597→      if (onOutput) {
598→        outputChain.then(() => {
599→          logger.info(
600→            { group: group.name, duration, newSessionId },
601→            'Container completed (streaming mode)',
602→          );
603→          resolve({
604→            status: 'success',
605→            result: null,
606→            newSessionId,
607→          });
608→        });
609→        return;
610→      }
611→
612→      // Legacy mode: parse the last output marker pair from accumulated stdout
613→      try {
614→        // Extract JSON between sentinel markers for robust parsing
615→        const startIdx = stdout.indexOf(OUTPUT_START_MARKER);
616→        const endIdx = stdout.indexOf(OUTPUT_END_MARKER);
617→
618→        let jsonLine: string;
619→        if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
620→          jsonLine = stdout
621→            .slice(startIdx + OUTPUT_START_MARKER.length, endIdx)
622→            .trim();
623→        } else {
624→          // Fallback: last non-empty line (backwards compatibility)
625→          const lines = stdout.trim().split('\n');
626→          jsonLine = lines[lines.length - 1];
627→        }
628→
629→        const output: ContainerOutput = JSON.parse(jsonLine);
630→
631→        logger.info(
632→          {
633→            group: group.name,
634→            duration,
635→            status: output.status,
636→            hasResult: !!output.result,
637→          },
638→          'Container completed',
639→        );
640→
641→        resolve(output);
642→      } catch (err) {
643→        logger.error(
644→          {
645→            group: group.name,
646→            stdout,
647→            stderr,
648→            error: err,
649→          },
650→          'Failed to parse container output',
651→        );
652→
653→        resolve({
654→          status: 'error',
655→          result: null,
656→          error: `Failed to parse container output: ${err instanceof Error ? err.message : String(err)}`,
657→        });
658→      }
659→    });
660→
661→    container.on('error', (err) => {
662→      clearTimeout(timeout);
663→      logger.error(
664→        { group: group.name, containerName, error: err },
665→        'Container spawn error',
666→      );
667→      resolve({
668→        status: 'error',
669→        result: null,
670→        error: `Container spawn error: ${err.message}`,
671→      });
672→    });
673→  });
674→}
675→
676→export function writeTasksSnapshot(
677→  groupFolder: string,
678→  isMain: boolean,
679→  tasks: Array<{
680→    id: string;
681→    groupFolder: string;
682→    prompt: string;
683→    schedule_type: string;
684→    schedule_value: string;
685→    status: string;
686→    next_run: string | null;
687→  }>,
688→): void {
689→  // Write filtered tasks to the group's IPC directory
690→  const groupIpcDir = resolveGroupIpcPath(groupFolder);
691→  fs.mkdirSync(groupIpcDir, { recursive: true });
692→
693→  // Main sees all tasks, others only see their own
694→  const filteredTasks = isMain
695→    ? tasks
696→    : tasks.filter((t) => t.groupFolder === groupFolder);
697→
698→  const tasksFile = path.join(groupIpcDir, 'current_tasks.json');
699→  fs.writeFileSync(tasksFile, JSON.stringify(filteredTasks, null, 2));
700→}
701→
702→export interface AvailableGroup {
703→  jid: string;
704→  name: string;
705→  lastActivity: string;
706→  isRegistered: boolean;
707→}
708→
709→/**
710→ * Write available groups snapshot for the container to read.
711→ * Only main group can see all available groups (for activation).
712→ * Non-main groups only see their own registration status.
713→ */
714→export function writeGroupsSnapshot(
715→  groupFolder: string,
716→  isMain: boolean,
717→  groups: AvailableGroup[],
718→  _registeredJids: Set<string>,
719→): void {
720→  const groupIpcDir = resolveGroupIpcPath(groupFolder);
721→  fs.mkdirSync(groupIpcDir, { recursive: true });
722→
723→  // Main sees all groups; others see nothing (they can't activate groups)
724→  const visibleGroups = isMain ? groups : [];
725→
726→  const groupsFile = path.join(groupIpcDir, 'available_groups.json');
727→  fs.writeFileSync(
728→    groupsFile,
729→    JSON.stringify(
730→      {
731→        groups: visibleGroups,
732→        lastSync: new Date().toISOString(),
733→      },
734→      null,
735→      2,
736→    ),
737→  );
738→}
