 12→
 13→export interface IpcDeps {
 14→  sendMessage: (jid: string, text: string) => Promise<void>;
 15→  registeredGroups: () => Record<string, RegisteredGroup>;
 16→  registerGroup: (jid: string, group: RegisteredGroup) => void;
