 28→let ipcWatcherRunning = false;
 29→
 30→export function startIpcWatcher(deps: IpcDeps): void {
 31→  if (ipcWatcherRunning) {
 32→    logger.debug('IPC watcher already running, skipping duplicate start');
 33→    return;
 34→  }
 35→  ipcWatcherRunning = true;
 36→
 37→  const ipcBaseDir = path.join(DATA_DIR, 'ipc');
 38→  fs.mkdirSync(ipcBaseDir, { recursive: true });
 39→
 40→  const processIpcFiles = async () => {
 41→    // Scan all group IPC directories (identity determined by directory)
 42→    let groupFolders: string[];
 43→    try {
 44→      groupFolders = fs.readdirSync(ipcBaseDir).filter((f) => {
 45→        const stat = fs.statSync(path.join(ipcBaseDir, f));
 46→        return stat.isDirectory() && f !== 'errors';
 47→      });
 48→    } catch (err) {
 49→      logger.error({ err }, 'Error reading IPC base directory');
 50→      setTimeout(processIpcFiles, IPC_POLL_INTERVAL);
 51→      return;
 52→    }
 53→
 54→    const registeredGroups = deps.registeredGroups();
 55→
 56→    // Build folder→isMain lookup from registered groups
 57→    const folderIsMain = new Map<string, boolean>();
 58→    for (const group of Object.values(registeredGroups)) {
 59→      if (group.isMain) folderIsMain.set(group.folder, true);
 60→    }
 61→
 62→    for (const sourceGroup of groupFolders) {
 63→      const isMain = folderIsMain.get(sourceGroup) === true;
 64→      const messagesDir = path.join(ipcBaseDir, sourceGroup, 'messages');
 65→      const tasksDir = path.join(ipcBaseDir, sourceGroup, 'tasks');
 66→
 67→      // Process messages from this group's IPC directory
 68→      try {
 69→        if (fs.existsSync(messagesDir)) {
 70→          const messageFiles = fs
 71→            .readdirSync(messagesDir)
 72→            .filter((f) => f.endsWith('.json'));
 73→          for (const file of messageFiles) {
 74→            const filePath = path.join(messagesDir, file);
 75→            try {
 76→              const data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
 77→              if (data.type === 'message' && data.chatJid && data.text) {
 78→                // Authorization: verify this group can send to this chatJid
 79→                const targetGroup = registeredGroups[data.chatJid];
 80→                if (
 81→                  isMain ||
 82→                  (targetGroup && targetGroup.folder === sourceGroup)
 83→                ) {
 84→                  await deps.sendMessage(data.chatJid, data.text);
 85→                  logger.info(
 86→                    { chatJid: data.chatJid, sourceGroup },
 87→                    'IPC message sent',
 88→                  );
 89→                } else {
 90→                  logger.warn(
 91→                    { chatJid: data.chatJid, sourceGroup },
 92→                    'Unauthorized IPC message attempt blocked',
 93→                  );
 94→                }
 95→              }
 96→              fs.unlinkSync(filePath);
 97→            } catch (err) {
 98→              logger.error(
 99→                { file, sourceGroup, err },
100→                'Error processing IPC message',
101→              );
102→              const errorDir = path.join(ipcBaseDir, 'errors');
103→              fs.mkdirSync(errorDir, { recursive: true });
104→              fs.renameSync(
105→                filePath,
106→                path.join(errorDir, `${sourceGroup}-${file}`),
107→              );
108→            }
109→          }
110→        }
111→      } catch (err) {
112→        logger.error(
113→          { err, sourceGroup },
114→          'Error reading IPC messages directory',
115→        );
116→      }
117→
118→      // Process tasks from this group's IPC directory
119→      try {
120→        if (fs.existsSync(tasksDir)) {
121→          const taskFiles = fs
122→            .readdirSync(tasksDir)
123→            .filter((f) => f.endsWith('.json'));
124→          for (const file of taskFiles) {
125→            const filePath = path.join(tasksDir, file);
126→            try {
127→              const data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
128→              // Pass source group identity to processTaskIpc for authorization
129→              await processTaskIpc(data, sourceGroup, isMain, deps);
130→              fs.unlinkSync(filePath);
131→            } catch (err) {
132→              logger.error(
133→                { file, sourceGroup, err },
134→                'Error processing IPC task',
135→              );
136→              const errorDir = path.join(ipcBaseDir, 'errors');
137→              fs.mkdirSync(errorDir, { recursive: true });
138→              fs.renameSync(
139→                filePath,
140→                path.join(errorDir, `${sourceGroup}-${file}`),
141→              );
142→            }
143→          }
144→        }
145→      } catch (err) {
146→        logger.error({ err, sourceGroup }, 'Error reading IPC tasks directory');
147→      }
148→    }
149→
150→    setTimeout(processIpcFiles, IPC_POLL_INTERVAL);
151→  };
152→
153→  processIpcFiles();
154→  logger.info('IPC watcher started (per-group namespaces)');
155→}
