157→export async function processTaskIpc(
158→  data: {
159→    type: string;
160→    taskId?: string;
161→    prompt?: string;
162→    schedule_type?: string;
163→    schedule_value?: string;
164→    context_mode?: string;
165→    groupFolder?: string;
166→    chatJid?: string;
167→    targetJid?: string;
168→    // For register_group
169→    jid?: string;
170→    name?: string;
171→    folder?: string;
172→    trigger?: string;
173→    requiresTrigger?: boolean;
174→    containerConfig?: RegisteredGroup['containerConfig'];
175→  },
176→  sourceGroup: string, // Verified identity from IPC directory
177→  isMain: boolean, // Verified from directory path
178→  deps: IpcDeps,
179→): Promise<void> {
180→  const registeredGroups = deps.registeredGroups();
181→
182→  switch (data.type) {
183→    case 'schedule_task':
184→      if (
185→        data.prompt &&
186→        data.schedule_type &&
187→        data.schedule_value &&
188→        data.targetJid
189→      ) {
190→        // Resolve the target group from JID
191→        const targetJid = data.targetJid as string;
192→        const targetGroupEntry = registeredGroups[targetJid];
193→
194→        if (!targetGroupEntry) {
195→          logger.warn(
196→            { targetJid },
197→            'Cannot schedule task: target group not registered',
198→          );
199→          break;
200→        }
201→
202→        const targetFolder = targetGroupEntry.folder;
203→
204→        // Authorization: non-main groups can only schedule for themselves
205→        if (!isMain && targetFolder !== sourceGroup) {
206→          logger.warn(
207→            { sourceGroup, targetFolder },
208→            'Unauthorized schedule_task attempt blocked',
209→          );
210→          break;
211→        }
212→
213→        const scheduleType = data.schedule_type as 'cron' | 'interval' | 'once';
214→
215→        let nextRun: string | null = null;
216→        if (scheduleType === 'cron') {
217→          try {
218→            const interval = CronExpressionParser.parse(data.schedule_value, {
219→              tz: TIMEZONE,
220→            });
221→            nextRun = interval.next().toISOString();
222→          } catch {
223→            logger.warn(
224→              { scheduleValue: data.schedule_value },
225→              'Invalid cron expression',
226→            );
227→            break;
228→          }
229→        } else if (scheduleType === 'interval') {
230→          const ms = parseInt(data.schedule_value, 10);
231→          if (isNaN(ms) || ms <= 0) {
232→            logger.warn(
233→              { scheduleValue: data.schedule_value },
234→              'Invalid interval',
235→            );
236→            break;
237→          }
238→          nextRun = new Date(Date.now() + ms).toISOString();
239→        } else if (scheduleType === 'once') {
240→          const date = new Date(data.schedule_value);
241→          if (isNaN(date.getTime())) {
242→            logger.warn(
243→              { scheduleValue: data.schedule_value },
244→              'Invalid timestamp',
245→            );
246→            break;
247→          }
248→          nextRun = date.toISOString();
249→        }
250→
251→        const taskId =
252→          data.taskId ||
253→          `task-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
254→        const contextMode =
255→          data.context_mode === 'group' || data.context_mode === 'isolated'
256→            ? data.context_mode
257→            : 'isolated';
258→        createTask({
259→          id: taskId,
260→          group_folder: targetFolder,
261→          chat_jid: targetJid,
262→          prompt: data.prompt,
263→          schedule_type: scheduleType,
264→          schedule_value: data.schedule_value,
265→          context_mode: contextMode,
266→          next_run: nextRun,
267→          status: 'active',
268→          created_at: new Date().toISOString(),
269→        });
270→        logger.info(
271→          { taskId, sourceGroup, targetFolder, contextMode },
272→          'Task created via IPC',
273→        );
274→        deps.onTasksChanged();
275→      }
276→      break;
277→
278→    case 'pause_task':
279→      if (data.taskId) {
280→        const task = getTaskById(data.taskId);
281→        if (task && (isMain || task.group_folder === sourceGroup)) {
282→          updateTask(data.taskId, { status: 'paused' });
283→          logger.info(
284→            { taskId: data.taskId, sourceGroup },
285→            'Task paused via IPC',
286→          );
287→          deps.onTasksChanged();
288→        } else {
289→          logger.warn(
290→            { taskId: data.taskId, sourceGroup },
291→            'Unauthorized task pause attempt',
292→          );
293→        }
294→      }
295→      break;
296→
297→    case 'resume_task':
298→      if (data.taskId) {
299→        const task = getTaskById(data.taskId);
300→        if (task && (isMain || task.group_folder === sourceGroup)) {
301→          updateTask(data.taskId, { status: 'active' });
302→          logger.info(
303→            { taskId: data.taskId, sourceGroup },
304→            'Task resumed via IPC',
305→          );
306→          deps.onTasksChanged();
307→        } else {
308→          logger.warn(
309→            { taskId: data.taskId, sourceGroup },
310→            'Unauthorized task resume attempt',
311→          );
312→        }
313→      }
314→      break;
315→
316→    case 'cancel_task':
317→      if (data.taskId) {
318→        const task = getTaskById(data.taskId);
319→        if (task && (isMain || task.group_folder === sourceGroup)) {
320→          deleteTask(data.taskId);
321→          logger.info(
322→            { taskId: data.taskId, sourceGroup },
323→            'Task cancelled via IPC',
324→          );
325→          deps.onTasksChanged();
326→        } else {
327→          logger.warn(
328→            { taskId: data.taskId, sourceGroup },
329→            'Unauthorized task cancel attempt',
330→          );
331→        }
332→      }
333→      break;
334→
335→    case 'update_task':
336→      if (data.taskId) {
337→        const task = getTaskById(data.taskId);
338→        if (!task) {
339→          logger.warn(
340→            { taskId: data.taskId, sourceGroup },
341→            'Task not found for update',
342→          );
343→          break;
344→        }
345→        if (!isMain && task.group_folder !== sourceGroup) {
346→          logger.warn(
347→            { taskId: data.taskId, sourceGroup },
348→            'Unauthorized task update attempt',
349→          );
350→          break;
351→        }
352→
353→        const updates: Parameters<typeof updateTask>[1] = {};
354→        if (data.prompt !== undefined) updates.prompt = data.prompt;
355→        if (data.schedule_type !== undefined)
356→          updates.schedule_type = data.schedule_type as
357→            | 'cron'
358→            | 'interval'
359→            | 'once';
360→        if (data.schedule_value !== undefined)
361→          updates.schedule_value = data.schedule_value;
362→
363→        // Recompute next_run if schedule changed
364→        if (data.schedule_type || data.schedule_value) {
365→          const updatedTask = {
366→            ...task,
367→            ...updates,
368→          };
369→          if (updatedTask.schedule_type === 'cron') {
370→            try {
371→              const interval = CronExpressionParser.parse(
372→                updatedTask.schedule_value,
373→                { tz: TIMEZONE },
374→              );
375→              updates.next_run = interval.next().toISOString();
376→            } catch {
377→              logger.warn(
378→                { taskId: data.taskId, value: updatedTask.schedule_value },
379→                'Invalid cron in task update',
380→              );
381→              break;
382→            }
383→          } else if (updatedTask.schedule_type === 'interval') {
384→            const ms = parseInt(updatedTask.schedule_value, 10);
385→            if (!isNaN(ms) && ms > 0) {
386→              updates.next_run = new Date(Date.now() + ms).toISOString();
387→            }
388→          }
389→        }
390→
391→        updateTask(data.taskId, updates);
392→        logger.info(
393→          { taskId: data.taskId, sourceGroup, updates },
