165→export function storeChatMetadata(
166→  chatJid: string,
167→  timestamp: string,
168→  name?: string,
169→  channel?: string,
170→  isGroup?: boolean,
171→): void {
172→  const ch = channel ?? null;
173→  const group = isGroup === undefined ? null : isGroup ? 1 : 0;
174→
175→  if (name) {
176→    // Update with name, preserving existing timestamp if newer
177→    db.prepare(
