192→      ON CONFLICT(jid) DO UPDATE SET
193→        last_message_time = MAX(last_message_time, excluded.last_message_time),
194→        channel = COALESCE(excluded.channel, channel),
195→        is_group = COALESCE(excluded.is_group, is_group)
196→    `,
197→    ).run(chatJid, chatJid, timestamp, ch, group);
198→  }
