305→export function getNewMessages(
306→  jids: string[],
307→  lastTimestamp: string,
308→  botPrefix: string,
309→  limit: number = 200,
310→): { messages: NewMessage[]; newTimestamp: string } {
311→  if (jids.length === 0) return { messages: [], newTimestamp: lastTimestamp };
312→
313→  const placeholders = jids.map(() => '?').join(',');
314→  // Filter bot messages using both the is_bot_message flag AND the content
315→  // prefix as a backstop for messages written before the migration ran.
316→  // Subquery takes the N most recent, outer query re-sorts chronologically.
317→  const sql = `
318→    SELECT * FROM (
319→      SELECT id, chat_jid, sender, sender_name, content, timestamp, is_from_me
320→      FROM messages
321→      WHERE timestamp > ? AND chat_jid IN (${placeholders})
322→        AND is_bot_message = 0 AND content NOT LIKE ?
323→        AND content != '' AND content IS NOT NULL
324→      ORDER BY timestamp DESC
325→      LIMIT ?
326→    ) ORDER BY timestamp
327→  `;
328→
329→  const rows = db
330→    .prepare(sql)
331→    .all(lastTimestamp, ...jids, `${botPrefix}:%`, limit) as NewMessage[];
332→
333→  let newTimestamp = lastTimestamp;
334→  for (const row of rows) {
335→    if (row.timestamp > newTimestamp) newTimestamp = row.timestamp;
336→  }
337→
338→  return { messages: rows, newTimestamp };
339→}
