607→    added_at: string;
608→    container_config: string | null;
609→    requires_trigger: number | null;
610→    is_main: number | null;
611→  }>;
612→  const result: Record<string, RegisteredGroup> = {};
613→  for (const row of rows) {
614→    if (!isValidGroupFolder(row.folder)) {
615→      logger.warn(
616→        { jid: row.jid, folder: row.folder },
617→        'Skipping registered group with invalid folder',
618→      );
619→      continue;
620→    }
621→    result[row.jid] = {
622→      name: row.name,
623→      folder: row.folder,
624→      trigger: row.trigger_pattern,
625→      added_at: row.added_at,
626→      containerConfig: row.container_config
627→        ? JSON.parse(row.container_config)
628→        : undefined,
629→      requiresTrigger:
630→        row.requires_trigger === null ? undefined : row.requires_trigger === 1,
631→      isMain: row.is_main === 1 ? true : undefined,
632→    };
633→  }
634→  return result;
