637→// --- JSON migration ---
638→
639→function migrateJsonState(): void {
640→  const migrateFile = (filename: string) => {
641→    const filePath = path.join(DATA_DIR, filename);
642→    if (!fs.existsSync(filePath)) return null;
643→    try {
644→      const data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
645→      fs.renameSync(filePath, `${filePath}.migrated`);
646→      return data;
647→    } catch {
648→      return null;
649→    }
650→  };
651→
652→  // Migrate router_state.json
653→  const routerState = migrateFile('router_state.json') as {
654→    last_timestamp?: string;
655→    last_agent_timestamp?: Record<string, string>;
656→  } | null;
657→  if (routerState) {
658→    if (routerState.last_timestamp) {
659→      setRouterState('last_timestamp', routerState.last_timestamp);
660→    }
661→    if (routerState.last_agent_timestamp) {
662→      setRouterState(
663→        'last_agent_timestamp',
664→        JSON.stringify(routerState.last_agent_timestamp),
665→      );
666→    }
667→  }
668→
669→  // Migrate sessions.json
670→  const sessions = migrateFile('sessions.json') as Record<
671→    string,
672→    string
673→  > | null;
674→  if (sessions) {
675→    for (const [folder, sessionId] of Object.entries(sessions)) {
676→      setSession(folder, sessionId);
677→    }
678→  }
679→
680→  // Migrate registered_groups.json
681→  const groups = migrateFile('registered_groups.json') as Record<
682→    string,
683→    RegisteredGroup
684→  > | null;
685→  if (groups) {
686→    for (const [jid, group] of Object.entries(groups)) {
687→      try {
688→        setRegisteredGroup(jid, group);
689→      } catch (err) {
690→        logger.warn(
691→          { jid, folder: group.folder, err },
692→          'Skipping migrated registered group with invalid folder',
693→        );
694→      }
695→    }
696→  }
697→}
